<?php
require 'config.php'; require_role(['admin','gso']);$user=current_user();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 try{
  if(isset($_POST['add_vehicle'])){$name=trim($_POST['vehicle_name']);$plate=trim($_POST['plate_number']);$type=trim($_POST['vehicle_type']);$cap=max(1,(int)$_POST['capacity']);$stmt=$conn->prepare('INSERT INTO vehicles(vehicle_name,plate_number,vehicle_type,capacity) VALUES(?,?,?,?)');$stmt->bind_param('sssi',$name,$plate,$type,$cap);$stmt->execute();log_activity($conn,null,'Vehicle added',$name.' · '.$plate);}
  if(isset($_POST['add_driver'])){$name=trim($_POST['full_name']);$phone=trim($_POST['phone']);$stmt=$conn->prepare('INSERT INTO drivers(full_name,phone) VALUES(?,?)');$stmt->bind_param('ss',$name,$phone);$stmt->execute();log_activity($conn,null,'Driver added',$name);}
  if(isset($_POST['vehicle_status'])){$id=(int)$_POST['id'];$status=$_POST['status']??'';if(!in_array($status,['Available','In Use','Maintenance','Inactive'],true))throw new Exception('Invalid status.');$stmt=$conn->prepare('UPDATE vehicles SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();log_activity($conn,null,'Vehicle status changed','#'.$id.' → '.$status);}
  go('vehicles.php');
 }catch(Throwable $e){$error='Unable to save. Check that the plate number is unique and all fields are valid.';}
}
$vs=$conn->query('SELECT * FROM vehicles ORDER BY vehicle_name');$ds=$conn->query('SELECT * FROM drivers ORDER BY full_name');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Vehicles & Drivers</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><span class="brand-icon">⌖</span><span>VEHICLE<br><small>RESERVATION</small></span></a><div class="side-label">WORKSPACE</div><nav><a href="dashboard.php">▦ <span>Dashboard</span></a><a href="reservations.php">▤ <span>Reservations</span></a><a class="active" href="vehicles.php">🚙 <span>Vehicles & Drivers</span></a><a href="activity.php">◷ <span>Activity Log</span></a></nav><div class="side-bottom"><a href="logout.php">↪ <span>Sign out</span></a></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/</span> Vehicles & Drivers</div><div class="user-chip"><div class="avatar"><?=h(strtoupper(substr($user['name'],0,1)))?></div><div><b><?=h($user['name'])?></b><small><?=h(strtoupper($user['role']))?></small></div></div></header><section class="welcome-row"><div><span class="eyebrow">FLEET MANAGEMENT</span><h1>Vehicles & drivers</h1><p>Maintain fleet availability and driver records.</p></div></section><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="bottom-grid"><section class="content-card"><div class="section-head"><div><h2>Add a vehicle</h2><p>Register a municipal unit.</p></div></div><form method="post" class="stack"><?=csrf_field()?><label>Vehicle name<input name="vehicle_name" required placeholder="Municipal Van"></label><label>Plate number<input name="plate_number" required placeholder="GOV-101"></label><label>Vehicle type<input name="vehicle_type" required placeholder="Van / Ambulance / SUV"></label><label>Passenger capacity<input type="number" min="1" name="capacity" value="4" required></label><button class="btn primary" name="add_vehicle">Add vehicle</button></form></section><section class="content-card"><div class="section-head"><div><h2>Add a driver</h2><p>Maintain driver contact and availability.</p></div></div><form method="post" class="stack"><?=csrf_field()?><label>Driver full name<input name="full_name" required placeholder="Full name"></label><label>Contact number<input name="phone" placeholder="09xx xxx xxxx"></label><button class="btn primary" name="add_driver">Add driver</button></form></section></div><section class="content-card"><div class="section-head"><div><h2>Fleet inventory</h2><p>Update a vehicle's status when required.</p></div></div><div class="table-wrap"><table><thead><tr><th>VEHICLE</th><th>PLATE</th><th>TYPE</th><th>CAPACITY</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody><?php while($v=$vs->fetch_assoc()):?><tr><td><b><?=h($v['vehicle_name'])?></b></td><td><?=h($v['plate_number'])?></td><td><?=h($v['vehicle_type'])?></td><td><?=h($v['capacity'])?></td><td><span class="status"><?=h($v['status'])?></span></td><td><form method="post" class="tiny-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$v['id']?>"><select name="status"><?php foreach(['Available','In Use','Maintenance','Inactive'] as $s):?><option <?=$v['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button name="vehicle_status" class="btn small-btn">Save</button></form></td></tr><?php endwhile;?></tbody></table></div></section><section class="content-card"><div class="section-head"><div><h2>Driver directory</h2><p>Current driver status.</p></div></div><div class="table-wrap"><table><thead><tr><th>DRIVER</th><th>CONTACT</th><th>STATUS</th></tr></thead><tbody><?php while($d=$ds->fetch_assoc()):?><tr><td><?=h($d['full_name'])?></td><td><?=h($d['phone'])?></td><td><span class="status"><?=h($d['status'])?></span></td></tr><?php endwhile;?></tbody></table></div></section><footer>© <?=date('Y')?> LGU Inabanga, Bohol</footer></main></div></body></html>
